### Iteration 3: Loop Unrolling and Register Blocking
I'll add loop unrolling to reduce branch overhead and use register blocking to increase arithmetic intensity. This should further improve performance.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define optimized CUDA kernel with loop unrolling and register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int n) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Row and column of the C element to compute
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int num_tiles = (n + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {
        // Prefetch multiple tiles
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int t_idx = t + u;
            if (t_idx < num_tiles) {
                // Load tile of A into shared memory
                int a_col = t_idx * TILE_SIZE + tx;
                if (row < n && a_col < n) {
                    As[ty][tx] = A[row * n + a_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                // Load tile of B into shared memory
                int b_row = t_idx * TILE_SIZE + ty;
                if (b_row < n && col < n) {
                    Bs[ty][tx] = B[b_row * n + col];
                } else {
                    Bs[ty][tx] = 0.0f;
                }

                __syncthreads();

                // Compute partial sum for this tile
                float partial_sum = 0.0f;
                for (int k = 0; k < TILE_SIZE; k++) {
                    partial_sum += As[ty][k] * Bs[k][tx];
                }
                sum += partial_sum;

                __syncthreads();
            }
        }
    }

    // Write result to global memory
    if (row < n && col < n) {
        C[row * n + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int n = A.size(0);
    auto C = torch::zeros({n, n}, A.options());

    dim3 blockDim(TILE_SIZE, TILE_SIZE);
    dim3 gridDim((n + TILE_SIZE - 1) / TILE_SIZE, 
                 (n + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), 
                                         B.data_ptr<float>(), 
                                         C.data_ptr<float>(), 
                                         n);
    return C;
}
"""

